#!/usr/bin/env python3
"""Generate source-compatible Ponko C spellings over the stable native ABI."""
from pathlib import Path
import re
import sys

root = Path(__file__).resolve().parent.parent
legacy = (root / 'include/crabby.h').read_text()
names = sorted(set(re.findall(r'\b(?:crabby_[A-Za-z0-9_]+|Crabby[A-Za-z0-9_]+|CRABBY_[A-Za-z0-9_]+)\b', legacy)))
lines = [
    '/* Generated by scripts/generate-ponko-header.py; do not edit. */',
    '/* Source aliases retain the version-2 binary ABI. Dynamic lookup uses legacy symbols. */',
    '#ifndef PONKO_H', '#define PONKO_H', '#include "crabby.h"', '',
]
for name in names:
    if name == 'CRABBY_H':
        continue
    alias = name.replace('crabby_', 'ponko_', 1).replace('Crabby', 'Ponko', 1).replace('CRABBY_', 'PONKO_', 1)
    lines.append(f'#define {alias} {name}')
lines += ['', '#endif', '']
output = '\n'.join(lines)
path = root / 'include/ponko.h'
if '--check' in sys.argv:
    if not path.exists() or path.read_text() != output:
        sys.exit('include/ponko.h is stale; run scripts/generate-ponko-header.py')
else:
    path.write_text(output)
